input.command:
cd ~/.claude/projects
echo "=== Claude Code today: output tokens by project, and workflow vs main ==="
find . -name '*.jsonl' -newermt '2026-06-10 00:00' 2>/dev/null | while read f; do
  proj=$(echo "$f" | cut -d/ -f2)
  kind=$(echo "$f" | grep -q '/subagents/workflows/' && echo workflow || { echo "$f" | grep -q '/subagents/' && echo subagent || echo main; })
  out=$(jq -rc 'select(.message.usage) | (.message.usage.output_tokens//0)' "$f" 2>/dev/null | awk '{s+=$1} END{print s+0}')
  cw=$(jq -rc 'select(.message.usage) | (.message.usage.cache_creation_input_tokens//0)' "$f" 2>/dev/null | awk '{s+=$1} END{print s+0}')
  echo -e "$proj\t$kind\t$out\t$cw"
done | awk -F'\t' '{po[$1]+=$3; pcw[$1]+=$4; ko[$2]+=$3; kcw[$2]+=$4} END{
  print "-- by project (output / cacheWrite tokens) --";
  for(p in po) printf "  %-44s out=%9d cacheWrite=%10d\n", p, po[p], pcw[p];
  print "-- by kind --";
  for(k in ko) printf "  %-12s out=%9d cacheWrite=%10d\n", k, ko[k], kcw[k];
}' | sort

