input.command:
cd ~/.claude/projects
echo "=== TOOL ATTRIBUTION (today) — calls, args bytes, RESULT bytes (context injected) ==="
find . -name '*.jsonl' -newermt '2026-06-10 00:00' 2>/dev/null -print0 \
| xargs -0 cat 2>/dev/null \
| jq -rc 'select(.message.content | type=="array")
  | .message.content[]
  | if .type=="tool_use" then ["U", .id, .name, ((.input|tostring)|length)]
    elif .type=="tool_result" then ["R", .tool_use_id, ((.content|tostring)|length)]
    else empty end | @tsv' 2>/dev/null \
| awk -F'\t' '
  $1=="U"{ name[$2]=$3; cnt[$3]++; args[$3]+=$4 }
  $1=="R"{ rbyId[$2]+=$3 }
  END{
    for(id in rbyId){ rb[name[id]] += rbyId[id] }
    printf "%-26s %8s %14s %14s\n","TOOL","calls","argBytes","resultBytes";
    for(t in cnt) printf "%-26s %8d %14d %14d\n", t, cnt[t], args[t], rb[t];
  }' | sort -k4 -rn | head -30

