input.command:
cd ~/.claude/projects
mkdir -p /tmp/audit
# combine today's transcripts once
find . -name '*.jsonl' -newermt '2026-06-10 00:00' 2>/dev/null -print0 | xargs -0 cat 2>/dev/null > /tmp/audit/all.jsonl
wc -l /tmp/audit/all.jsonl

echo "=== CACHE / TOKEN TOTALS (today, all Claude Code) ==="
jq -rc 'select(.message.usage) | [(.message.usage.input_tokens//0),(.message.usage.output_tokens//0),(.message.usage.cache_creation_input_tokens//0),(.message.usage.cache_read_input_tokens//0)] | @tsv' /tmp/audit/all.jsonl 2>/dev/null \
| awk -F'\t' '{i+=$1;o+=$2;cw+=$3;cr+=$4} END{
  printf "input(uncached): %15d\n", i;
  printf "output:          %15d\n", o;
  printf "cacheWrite:      %15d  (cache MISS / re-cache)\n", cw;
  printf "cacheRead:       %15d  (cache HIT / cheap re-read)\n", cr;
  printf "TOTAL:           %15d\n", i+o+cw+cr;
  printf "cacheWrite/cacheRead ratio: %.3f  (lower=better cache reuse)\n", cw/(cr+1);
}'

